import { sleep, log, stop } from "klickr";
import { inspectOnly } from "./walls.js";
import { all, number, snapshot, waitSnapshot, position, tapStep, act } from "./screen.js";
await sleep(5000);
const selected = await inspectOnly({goldReserve:1000000,elixirReserve:1000000});
if (!await act(selected,[tapStep(position(selected,"more"))])) await stop("Observação invalidada antes de abrir o lote.");
const controls = ['batchRemove','batchAdd','selected16','goldBatchAvailable1','goldBatchAvailable2','elixirBatchAvailable1','elixirBatchAvailable2'];
async function batch(total) {
 const current = await waitSnapshot('conferir lote de '+total,[...controls,'goldBatchCost','elixirBatchCost'],
  value => all(value,controls) && number(value.results.goldBatchCost)===total && number(value.results.elixirBatchCost)===total);
 await log(JSON.stringify({kind:'dry_batch_selection',total,results:current.results}));
 return current;
}
let current = await batch(2000000);
for (const [action,total] of [['more',4000000],['remove',2000000],['more',4000000]]) {
 if (!await act(current,[tapStep(position(current,action))])) await stop('Observação invalidada; inspeção encerrada.');
 current = await batch(total);
}
if (!await act(current,[tapStep(position(current,'goldPay'))])) await stop('Observação invalidada antes da confirmação.');
const names = ['batchTitle','batchOk','batchConfirmCost','goldLabel','elixirLabel'];
const checked = await waitSnapshot('inspecionar confirmação do lote sem pagar',names,
 value => all(value,['batchTitle','batchOk','goldLabel']) && number(value.results.batchConfirmCost)===4000000,
 {timeoutMs:5000,intervalMs:100,required:false});
const confirmation = checked ?? await snapshot(names);
await log(JSON.stringify({kind:'dry_batch_confirmation',verified:checked!==null,results:confirmation.results}));
await stop('Inspeção do lote encerrada antes de confirmar o pagamento.');
